using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Runtime.InteropServices;using System.Windows.Forms;using System.Text;using System.Text.RegularExpressions;
// Keep native selection, links and keyboard editing behavior; replace only the system scroll chrome.
class ThemedNotes : UserControl,IMessageFilter {
    [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr window,int message,IntPtr wParam,IntPtr lParam);
    internal readonly RichTextBox Editor;internal readonly NotesRail Rail;bool syncing,filterAdded;int wheelRemainder;string markdown;
    internal ThemedNotes(){SetStyle(ControlStyles.SupportsTransparentBackColor,true);BackColor=Color.Transparent;Editor=new WheelEditor(this){BorderStyle=BorderStyle.None,ReadOnly=true,ScrollBars=RichTextBoxScrollBars.None,WordWrap=true,DetectUrls=true,BackColor=PetTheme.Surface,ForeColor=PetTheme.Ink};Rail=new NotesRail(this);Controls.Add(Editor);Controls.Add(Rail);Editor.VScroll+=(s,e)=>Sync();Editor.TextChanged+=(s,e)=>Sync();Editor.FontChanged+=(s,e)=>Sync();Editor.Resize+=(s,e)=>Sync();PetTheme.Changed+=Recolor;}
    protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);if(!filterAdded){Application.AddMessageFilter(this);filterAdded=true;}}
    protected override void OnHandleDestroyed(EventArgs e){if(filterAdded){Application.RemoveMessageFilter(this);filterAdded=false;}base.OnHandleDestroyed(e);}
    protected override void Dispose(bool disposing){if(disposing){PetTheme.Changed-=Recolor;if(filterAdded){Application.RemoveMessageFilter(this);filterAdded=false;}}base.Dispose(disposing);}
    public bool PreFilterMessage(ref Message m){if(m.Msg!=0x20A||!Visible||!IsHandleCreated||!RectangleToScreen(ClientRectangle).Contains(Cursor.Position))return false;ScrollWheel((short)(m.WParam.ToInt64()>>16));return true;}
    internal void ScrollWheel(int delta){wheelRemainder+=delta;int steps=wheelRemainder/120;if(steps==0)return;wheelRemainder-=steps*120;int lines=SystemInformation.MouseWheelScrollLines;if(lines<0)lines=PageLines;if(lines>0)ScrollTo(FirstLine-steps*lines);}
    sealed class WheelEditor:RichTextBox {readonly ThemedNotes owner;internal WheelEditor(ThemedNotes owner){this.owner=owner;}protected override void WndProc(ref Message m){if(m.Msg==0x20A){owner.ScrollWheel((short)(m.WParam.ToInt64()>>16));m.Result=IntPtr.Zero;return;}base.WndProc(ref m);}}
    void Recolor(object sender,EventArgs e){if(markdown==null||IsDisposed)return;int first=FirstLine;SetMarkdown(markdown);MatchSurface();ScrollTo(first);}
    internal void SetMarkdown(string value){markdown=(value??"");if(markdown.Length>16000)markdown=markdown.Substring(0,16000);var rtf=new StringBuilder("{\\rtf1\\ansi\\deff0\\uc1{\\fonttbl{\\f0 ");AppendText(rtf,"Segoe UI");rtf.Append(";}}{\\colortbl ;\\red").Append(PetTheme.Ink.R).Append("\\green").Append(PetTheme.Ink.G).Append("\\blue").Append(PetTheme.Ink.B).Append(";}\\viewkind4\\lang1042\\f0\\cf1 ");foreach(string raw in markdown.Replace("\r","").Split('\n')){string line=raw.Trim();if(line.Length==0)continue;bool heading=line.StartsWith("#"),bullet=line.StartsWith("- ")||line.StartsWith("• ");if(heading)line=Regex.Replace(line,@"^#+\s*","");if(bullet)line=line.Substring(2);line=Regex.Replace(line,@"\[([^\]]+)\]\((https://[^)]+)\)","$1 ($2)");rtf.Append(heading?"\\pard\\li0\\fi0\\sa130\\sl280\\slmult0\\fs23\\b ":bullet?"\\pard\\li0\\fi0\\sa110\\sl280\\slmult0\\fs20\\b0 ":"\\pard\\li0\\fi0\\sa110\\sl280\\slmult0\\fs20\\b0 ");if(heading)AppendText(rtf,line.Replace("**",""));else AppendWords(rtf,line.Replace("**",""));rtf.Append("\\par ");}rtf.Append('}');Editor.Rtf=rtf.ToString();Editor.SelectionStart=0;Editor.SelectionLength=0;Sync();}
    void AppendWords(StringBuilder result,string text){using(var font=new Font("Segoe UI",10)){string current="";foreach(string word in text.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries)){string candidate=current.Length==0?word:current+" "+word;if(current.Length>0&&TextRenderer.MeasureText(candidate,font,new Size(Int32.MaxValue,Int32.MaxValue),TextFormatFlags.SingleLine|TextFormatFlags.NoPadding).Width>Math.Max(80,Editor.ClientSize.Width-10)){AppendText(result,current);result.Append("\\line ");current=word;}else current=candidate;}AppendText(result,current);}}
    static void AppendText(StringBuilder result,string text){foreach(char c in text){if(c=='\\'||c=='{'||c=='}')result.Append('\\').Append(c);else if(c>127)result.Append("\\u").Append((short)c).Append('?');else result.Append(c);}}
    internal int FirstLine {get{return Editor.IsHandleCreated?(int)SendMessage(Editor.Handle,0xCE,IntPtr.Zero,IntPtr.Zero):0;}}
    internal int PageLines {get{if(Editor.IsHandleCreated&&Editor.ClientSize.Height>5){int last=Editor.GetCharIndexFromPosition(new Point(1,Editor.ClientSize.Height-3));return Math.Max(1,Editor.GetLineFromCharIndex(last)-FirstLine+1);}return Math.Max(1,(int)((Editor.ClientSize.Height-5)/Math.Max(1,Editor.Font.GetHeight())));}}
    internal int LastLine {get{return Math.Max(0,Editor.GetLineFromCharIndex(Editor.TextLength)+1-PageLines);}}
    internal void ScrollTo(int value){value=Math.Max(0,Math.Min(LastLine,value));SendMessage(Editor.Handle,0xB6,IntPtr.Zero,(IntPtr)(value-FirstLine));Sync();}
    internal void Sync(){if(syncing||IsDisposed)return;syncing=true;try{Rail.Visible=LastLine>0;Rail.Invalidate();}finally{syncing=false;}}
    protected override void OnLayout(LayoutEventArgs e){base.OnLayout(e);if(Editor==null)return;Editor.Bounds=new Rectangle(10,8,Math.Max(1,Width-38),Math.Max(1,Height-16));Rail.Bounds=new Rectangle(Math.Max(0,Width-18),8,14,Math.Max(1,Height-16));Sync();}
    protected override void OnFontChanged(EventArgs e){base.OnFontChanged(e);if(Editor!=null)Editor.Font=Font;}
    void MatchSurface(){if(Editor==null)return;var root=FindForm() as GlassBubbleForm;Color color=PetTheme.Surface;if(root!=null){Point point=new Point(Width/2,Height/2);Control control=this;while(control!=root&&control!=null){point.Offset(control.Location);control=control.Parent;}color=root.SampleMaterial(point);}if(Editor.BackColor!=color)Editor.BackColor=color;}
    protected override void OnPaintBackground(PaintEventArgs e){PetTheme.PaintUnder(e.Graphics,this);MatchSurface();e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var shape=SettingArt.Round(new Rectangle(0,0,Math.Max(1,Width-1),Math.Max(1,Height-1)),16))using(var fill=new SolidBrush(Editor.BackColor))e.Graphics.FillPath(fill,shape);}
    internal sealed class NotesRail : Control {
        readonly ThemedNotes owner;bool dragging,hover;int grab;
        internal NotesRail(ThemedNotes owner){this.owner=owner;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.Selectable,true);TabStop=true;AccessibleRole=AccessibleRole.ScrollBar;AccessibleName="문서 세로 스크롤";Cursor=Cursors.Hand;}
        Rectangle Thumb {get{int height=Math.Max(28,(int)(Height*owner.PageLines/(double)(owner.LastLine+owner.PageLines))),travel=Math.Max(0,Height-height);return new Rectangle(4,(int)(travel*Math.Min(owner.LastLine,owner.FirstLine)/(double)Math.Max(1,owner.LastLine)),6,height);}}
        protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(owner.Editor.BackColor);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var track=new Pen(Color.FromArgb(55,PetTheme.Line),2))e.Graphics.DrawLine(track,7,3,7,Height-3);var thumb=Thumb;using(var shape=SettingArt.Round(thumb,3))using(var brush=new SolidBrush(dragging||hover?PetTheme.Accent:Color.FromArgb(180,PetTheme.Muted)))e.Graphics.FillPath(brush,shape);}
        protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}
        protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left)return;Focus();var thumb=Thumb;if(e.Y>=thumb.Top&&e.Y<=thumb.Bottom){dragging=true;grab=e.Y-thumb.Top;Capture=true;}else owner.ScrollTo(owner.FirstLine+(e.Y<thumb.Top?-owner.PageLines:owner.PageLines));}
        protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(dragging){int travel=Height-Thumb.Height;if(travel>0)owner.ScrollTo((int)Math.Round((e.Y-grab)*owner.LastLine/(double)travel));}}
        protected override void OnMouseUp(MouseEventArgs e){dragging=false;Capture=false;Invalidate();base.OnMouseUp(e);}
        protected override void OnMouseWheel(MouseEventArgs e){owner.ScrollWheel(e.Delta);base.OnMouseWheel(e);}
        protected override bool IsInputKey(Keys keyData){var key=keyData&Keys.KeyCode;return key==Keys.Left||key==Keys.Right||key==Keys.Up||key==Keys.Down||key==Keys.Home||key==Keys.End||key==Keys.PageUp||key==Keys.PageDown||base.IsInputKey(keyData);}
        protected override void OnKeyDown(KeyEventArgs e){int first=owner.FirstLine;switch(e.KeyCode){case Keys.Up:first--;break;case Keys.Down:first++;break;case Keys.PageUp:first-=owner.PageLines;break;case Keys.PageDown:first+=owner.PageLines;break;case Keys.Home:first=0;break;case Keys.End:first=owner.LastLine;break;default:base.OnKeyDown(e);return;}owner.ScrollTo(first);e.Handled=true;}
    }
}
